#include <Arduino.h>
#include <stdlib.h>
#include <ctype.h>
char buffer[32];
unsigned int used = 0;
bool overflowed = false;
unsigned long lastByte = 0;
void finishCommand() {
  if (!overflowed && used) {
    buffer[used] = '\0';
    char *end;
    long value = strtol(buffer, &end, 10);
    bool parsed = end != buffer;
    while (*end && isspace((unsigned char)*end)) ++end;
    if (parsed && !*end && value >= 0 && value <= 255) {
      analogWrite(9, (int)value);
      Serial.println(value);
    }
  }
  used = 0;
  overflowed = false;
}
void setup() {
  pinMode(9, OUTPUT);
  analogWrite(9, 0);
  Serial.begin(9600);
}
void loop() {
  while (Serial.available()) {
    if ((used || overflowed) && millis() - lastByte >= 20) finishCommand();
    char c = (char)Serial.read();
    lastByte = millis();
    if (c == '\n' || c == '\r') finishCommand();
    else if (used < sizeof(buffer) - 1) buffer[used++] = c;
    else overflowed = true;
  }
  if ((used || overflowed) && millis() - lastByte >= 20) finishCommand();
}
